mapper.select:
select session_id, user_id, context_data::text as context_data, summary, created_at, updated_at
from ai_session_context
where session_id = #{sessionId}

mapper.update:
update ai_session_context
context_data = CAST(#{contextData} AS jsonb), summary = #{summary}, updated_at = CURRENT_TIMESTAMP
where session_id = #{sessionId}
